(function(){
 'use strict';
 const drafts=new Map();let serial=0;
 const key=(p,d,e)=>JSON.stringify([p.studentId,p.id,d.id,e.id]);
 function saved(k){const n=state.workoutExerciseNotes?.[k];return n&&typeof n.text==='string'?n.text:''}
 function persist(k,text,status,button){
  const notes={...state.workoutExerciseNotes};if(text.trim())notes[k]={text:text.slice(0,2000),updatedAt:new Date().toISOString()};else delete notes[k];
  try{localStorage.setItem(DB_KEY,JSON.stringify({...state,workoutExerciseNotes:notes}));state.workoutExerciseNotes=notes;drafts.delete(k);const message=text.trim()?'Salva para os próximos treinos deste exercício.':'Espaço do professor. A observação fica para o próximo treino.';if(status.textContent!==message)status.textContent=message;status.classList.remove('is-error');button.disabled=!text.trim();window.APTeacherSync?.changed();return true}
  catch(_){drafts.set(k,text);status.textContent='Não foi possível salvar. Seu texto está aqui; toque fora do campo para tentar novamente.';status.classList.add('is-error');return false}
 }
 function add(section,p,day,ex){
  if(section.nextElementSibling?.classList.contains('ap-exercise-observation'))return;
  const k=key(p,day,ex),text=drafts.has(k)?drafts.get(k):saved(k),box=document.createElement('section'),id='apObservation'+(++serial);
  box.className='ap-exercise-observation';box.dataset.observationExercise=ex.id;
  const label=document.createElement('label');label.htmlFor=id;label.textContent='Observação deste aluno';
  const input=document.createElement('textarea');input.id=id;input.maxLength=2000;input.rows=2;input.placeholder='Ex.: relatou desconforto neste exercício. Conferir no próximo treino.';input.value=text;input.setAttribute('aria-describedby',id+'Status');
  const footer=document.createElement('div');footer.className='ap-exercise-observation-footer';const status=document.createElement('p');status.className='ap-exercise-observation-status';status.id=id+'Status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');
  status.textContent=drafts.has(k)?'Alteração ainda não salva. Toque fora do campo para tentar novamente.':text?'Salva para os próximos treinos deste exercício.':'Espaço do professor. A observação fica para o próximo treino.';
  const clear=document.createElement('button');clear.type='button';clear.className='btn ghost';clear.textContent='Apagar';clear.setAttribute('aria-label','Apagar observação de '+ex.name);clear.disabled=!text.trim();
  const editable=()=>{const current=currentWorkoutPlan(),d=currentWorkoutDay();return current?.id===p.id&&current.studentId===p.studentId&&d?.id===day.id&&d.exercises.some(e=>e.id===ex.id)&&!workoutPlanArchived(current)};
  input.oninput=()=>{if(!editable())return;persist(k,input.value,status,clear)};
  input.onblur=()=>{if(editable()&&drafts.has(k))persist(k,input.value,status,clear)};
  clear.onclick=()=>{if(!editable())return;if(persist(k,'',status,clear)){input.value='';input.focus({preventScroll:true})}};
  input.disabled=workoutPlanArchived(p);clear.disabled=input.disabled||clear.disabled;footer.append(status,clear);box.append(label,input,footer);section.after(box);
 }
 function decorateRoot(root,p,day){
  if(!root||!p||!day||workoutExercisesOrdering)return;
  for(const section of root.querySelectorAll('.ws-set-section[data-series-table]')){
   const ex=day.exercises.find(e=>e.id===section.dataset.seriesTable);if(ex)add(section,p,day,ex);
  }
 }
 function decorate(){
  const p=currentWorkoutPlan(),day=currentWorkoutDay();if(!p||!day)return;
  const root=document.getElementById('workoutDayContent');
  for(const card of root.querySelectorAll('.workout-exercise[data-exercise-id]')){
   if(!workoutRunning(p,day))continue;card.classList.add('ap-correctable');const details=card.querySelector('details[data-exercise-id]');if(details)details.open=true;
  }
  decorateRoot(root,p,day);
  for(const card of root.querySelectorAll('.workout-exercise[data-exercise-id]')){
   if(card.querySelector('.ap-exercise-observation'))continue;
   const ex=day.exercises.find(e=>e.id===card.dataset.exerciseId),last=card.classList.contains('ap-cardio-exercise')?card.querySelector('.ap-cardio-clock')||card.querySelector('.workout-exercise-layout'):card.querySelector('.workout-exercise-body')?.lastElementChild;if(ex&&last)add(last,p,day,ex);
  }
  compactCompleted(root,p,day);
  window.APCardioTeacher?.paint();
 }
 function validateInput(input){
  if(input.dataset.seriesField!=='reps'||Number.isInteger(Number(input.value))&&Number(input.value)>=1&&Number(input.value)<=999)return;
  const p=currentWorkoutPlan(),d=currentWorkoutDay();if(!p||!d)return;const round=Number(input.dataset.seriesRound),draft=state.workoutDrafts[workoutDraftKey(p.id,d.id)];
  const stored=input.dataset.seriesGroup?draft?.bisets?.[input.dataset.seriesGroup]?.rounds?.[round-1]?.[input.dataset.seriesPart]:draft?.values?.[input.dataset.seriesExercise]?.series?.[round];
  if(stored&&(input.dataset.seriesGroup||stored.done)){input.value=String(stored.reps);toast('Use de 1 a 999 repetições. O valor anterior foi mantido.')}
 }
 const expandedCompleted=new Set();let completedContext='';
 function completedRun(p,day){const draft=state.workoutDrafts[workoutDraftKey(p.id,day.id)];return JSON.stringify([p.studentId,p.id,day.id,draft?.sessionId||draft?.startedAt||''])}
 function removeCompletedSummary(card){
  const content=Array.from(card.children).find(n=>n.classList.contains('ap-teacher-completed-content'));
  card.querySelector('.ap-teacher-completed-toggle')?.remove();card.classList.remove('ap-teacher-completed-card');
  if(content){while(content.firstChild)card.insertBefore(content.firstChild,content);content.remove()}
 }
 function compactCompleted(root,p,day){
  const context=completedRun(p,day);if(context!==completedContext){expandedCompleted.clear();completedContext=context}
  const running=window.APTeacherFeatures?.enabled('compactCompleted')!==false&&workoutRunning(p,day)&&!workoutPlanArchived(p)&&!workoutExercisesOrdering;
  const draft=state.workoutDrafts[workoutDraftKey(p.id,day.id)];
  for(const card of root.querySelectorAll('.workout-exercise[data-exercise-id]')){
   const ex=day.exercises.find(e=>e.id===card.dataset.exerciseId),value=draft?.values?.[ex?.id],rows=value?.series?Object.values(value.series):[];
   const completed=running&&ex&&value?.done===true&&rows.length>0&&rows.every(row=>row.done===true);
   if(!completed){if(ex)expandedCompleted.delete(ex.id);removeCompletedSummary(card);continue}
   let content=Array.from(card.children).find(n=>n.classList.contains('ap-teacher-completed-content'));
   if(!content){content=document.createElement('div');content.className='ap-teacher-completed-content';content.id='apTeacherCompletedContent'+(++serial);while(card.firstChild)content.append(card.firstChild);card.append(content)}
   let button=card.querySelector('.ap-teacher-completed-toggle');
   if(!button){
    button=document.createElement('button');button.type='button';button.className='ap-teacher-completed-toggle';button.dataset.exerciseId=ex.id;button.setAttribute('aria-controls',content.id);
    const text=document.createElement('span');text.className='ap-teacher-completed-description';
    const name=document.createElement('strong');name.className='ap-teacher-completed-name';const summary=document.createElement('small');summary.className='ap-teacher-completed-prescription';text.append(name,summary);
    const status=document.createElement('span');status.className='ap-teacher-completed-status';
    const count=document.createElement('span');count.className='ap-teacher-completed-count';
    const arrow=document.createElementNS('http://www.w3.org/2000/svg','svg');arrow.setAttribute('viewBox','0 0 24 24');arrow.setAttribute('aria-hidden','true');arrow.setAttribute('focusable','false');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','m6 9 6 6 6-6');arrow.append(path);status.append(count,arrow);button.append(text,status);card.insertBefore(button,content);
   }
   button.querySelector('.ap-teacher-completed-name').textContent=ex.name;
   const prescription=APCardioTeacher.standalone(ex,day)?APCardio.label(ex):[ex.sets&&ex.reps?ex.sets+' × '+ex.reps:ex.sets?ex.sets+' séries':rows.length+' séries',ex.load].filter(Boolean).join(' · ');
   button.querySelector('.ap-teacher-completed-prescription').textContent=prescription;
   const count=button.querySelector('.ap-teacher-completed-count');count.textContent=APCardioTeacher.standalone(ex,day)?'✓':rows.length+'/'+rows.length;count.setAttribute('aria-label',APCardioTeacher.standalone(ex,day)?'Tempo concluído':rows.length+' de '+rows.length+' séries concluídas');
   function show(expanded){content.hidden=!expanded;button.setAttribute('aria-expanded',String(expanded));button.setAttribute('aria-label',(expanded?'Recolher':'Abrir')+' exercício concluído: '+ex.name)}
   button.onclick=()=>{const expanded=content.hidden;if(expanded)expandedCompleted.add(ex.id);else expandedCompleted.delete(ex.id);show(expanded)};
   card.classList.add('ap-teacher-completed-card');show(expandedCompleted.has(ex.id));
  }
 }
 function startTeacherSeriesRest(p,day,exerciseId,round){
  if(window.APTeacherFeatures?.enabled('autoRest')===false)return;
  if(currentWorkoutPlan()?.id!==p.id||currentWorkoutDay()?.id!==day.id||workoutPlanArchived(p)||!workoutRunning(p,day))return;
  const ex=day.exercises.find(e=>e.id===exerciseId);if(!ex)return;
  const active=state.workoutRest;if(active?.bisetId&&active.endAt>Date.now())return;
  const prescription=window.workoutTechniqueRoundPrescription?.(ex,round),specific=prescription?.restSeconds;
  const seconds=specific!==undefined&&specific!==null?Number(specific):workoutRestDuration(ex.rest);
  if(!Number.isInteger(seconds)||seconds<1||seconds>3600)return;
  try{
   openWorkoutRest(ex.id,false);
   document.getElementById('workoutRestSeconds').value=String(seconds);
   saveWorkoutRest({preventDefault(){}});
  }catch(_){toast('A série foi salva. Não foi possível iniciar o intervalo; use o botão Intervalo do exercício.',5500)}
 }

 const completeSeries=window.completeWorkoutSeriesCheck;
 window.completeWorkoutSeriesCheck=function(input){
  const p=currentWorkoutPlan(),day=currentWorkoutDay(),exerciseId=input?.dataset?.seriesExercise;
  const before=p&&day?state.workoutDrafts[workoutDraftKey(p.id,day.id)]?.values?.[exerciseId]?.done===true:false;
  const round=Number(input?.dataset?.seriesRound),checked=input?.checked===true,grouped=!!input?.dataset?.seriesGroup;
  const previous=p&&day?state.workoutDrafts[workoutDraftKey(p.id,day.id)]?.values?.[exerciseId]?.series?.[round]:null;
  if(!grouped&&checked&&previous?.done===true)return;
  const result=completeSeries.apply(this,arguments);
  if(p&&day&&!before&&!input?.dataset?.seriesGroup&&state.workoutDrafts[workoutDraftKey(p.id,day.id)]?.values?.[exerciseId]?.done===true){
   const root=document.getElementById('workoutDayContent'),card=Array.from(root?.querySelectorAll('.workout-exercise[data-exercise-id]')||[]).find(n=>n.dataset.exerciseId===exerciseId),button=card?.querySelector('.ap-teacher-completed-toggle');
   if(button){button.focus({preventScroll:true});button.scrollIntoView({block:'nearest'})}
  }
  if(p&&day&&!grouped&&checked&&previous?.done!==true){
   const saved=state.workoutDrafts[workoutDraftKey(p.id,day.id)]?.values?.[exerciseId]?.series?.[round];
   if(saved?.done===true)startTeacherSeriesRest(p,day,exerciseId,round);
  }
  return result;
 };

 const original=renderWorkoutDay;renderWorkoutDay=function(...args){const result=original(...args);decorate();return result};
 const completion=updateWorkoutExerciseCompletion;updateWorkoutExerciseCompletion=function(...args){const result=completion(...args);decorate();return result};
 try{window.parent.addEventListener('ap-account-changed',()=>{drafts.clear();expandedCompleted.clear();completedContext=''})}catch(_){}
 window.APWorkoutCorrections=Object.freeze({decorate,decorateGuide:(p,d)=>decorateRoot(document.getElementById('workoutBisetContent'),p,d),validateInput});
 decorate();
})();

(function(){
 'use strict';
 let scope=null, expanded=false;
 function decorate(){
  const dialog=document.getElementById('workoutStudentDialog');
  const section=dialog?.querySelector('#workoutStudentContent .workout-sheet-actions');
  const heading=section?.querySelector('#workoutSheetActionsTitle');
  const grid=section?.querySelector('.workout-sheet-action-grid');
  if(!heading||!grid||heading.querySelector('.ap-sheet-actions-toggle'))return;
  const nextScope=JSON.stringify([workoutStudentId,workoutPlanId,workoutPlanCollection]);
  if(scope!==nextScope||!dialog.classList.contains('open'))expanded=false;
  scope=nextScope;
  const button=document.createElement('button');
  button.type='button';
  button.className='ap-sheet-actions-toggle';
  button.setAttribute('aria-controls','apSheetActionsContent');
  button.append(...heading.childNodes);
  const arrow=document.createElement('span');
  arrow.className='ap-sheet-actions-chevron';
  arrow.setAttribute('aria-hidden','true');
  button.append(arrow);
  heading.append(button);
  section.classList.add('ap-sheet-actions-disclosure');
  const panel=document.createElement('div');
  panel.id='apSheetActionsContent';
  const note=section.querySelector('.workout-archive-note');
  grid.before(panel);
  panel.append(grid);
  if(note)panel.append(note);
  function sync(){
   button.setAttribute('aria-expanded',String(expanded));
   panel.hidden=!expanded;
  }
  button.addEventListener('click',()=>{expanded=!expanded;sync();});
  sync();
 }
 const render=renderWorkoutStudent;
 renderWorkoutStudent=function(...args){const result=render.apply(this,args);decorate();return result;};
 const open=openWorkoutStudent;
 openWorkoutStudent=function(...args){scope=null;expanded=false;return open.apply(this,args);};
})();

(function(){
  'use strict';

  const root = document.getElementById('workoutCatalogContent');
  const editorDelete = document.getElementById('workoutCatalogDelete');
  const personalTab = document.getElementById('workoutCatalogMine');
  const editCatalogId = document.getElementById('workoutExerciseCatalogId');
  if (!root || !personalTab || !editCatalogId) return;

  // The newer content already preserves removed catalog entries for old plans.
  // Provide the same lookup behavior on releases without the deletion update.
  if (!editorDelete) {
    const readAll = workoutCatalogItems;
    let includeRemoved = false;
    function withRemoved(read) {
      return function(...args) {
        const previous = includeRemoved;
        includeRemoved = true;
        try { return read(...args); }
        finally { includeRemoved = previous; }
      };
    }
    workoutCatalogItems = function() {
      const items = readAll();
      return includeRemoved ? items : items.filter(item => item.catalogRemoved !== true);
    };
    workoutExerciseVideoUrl = withRemoved(workoutExerciseVideoUrl);
    withWorkoutGuidance = withRemoved(withWorkoutGuidance);
    recoverWorkoutGalleryVideos = withRemoved(recoverWorkoutGalleryVideos);

    const saveCatalog = workoutCatalogChanges;
    workoutCatalogChanges = function(exercise) {
      if (workoutExerciseMode !== 'catalog' && !workoutCatalogItem(editCatalogId.value)) {
        const prior = readAll().find(item => item.catalogRemoved === true &&
          (item.id === editCatalogId.value || workoutCatalogSameName(exercise, item)));
        if (prior) return {catalogId: editCatalogId.value || prior.id, changes: {}};
      }
      return saveCatalog(exercise);
    };
  }

  function visibleGroups() {
    const unified = personalTab.hidden;
    const groups = new Map();
    const byId = new Map();
    for (const item of workoutCatalogItems()) {
      if (item.catalogRemoved === true) continue;
      const name = workoutSearchKey(item.name);
      const video = workoutYouTubeVideo(item.video)?.url ||
        normalizedWorkoutVideoUrl(item.video) || String(item.video || '').trim();
      const identity = name ? JSON.stringify([
        unified ? '' : item.source, name, workoutSearchKey(item.muscle),
        workoutSearchKey(item.category), video, workoutCatalogBlocked(item)
      ]) : item.id;
      if (!groups.has(identity)) groups.set(identity, {representative:item, ids:new Set()});
      const group = groups.get(identity);
      group.ids.add(item.id);
      if (item.source === 'mine' && group.representative.source !== 'mine') {
        group.representative = item;
      }
      byId.set(item.id, group);
    }
    return byId;
  }

  // Group cards at display time. IDs, instructions and videos remain available
  // in storage for any plan that refers to a particular catalog record.
  const filter = filteredWorkoutCatalog;
  filteredWorkoutCatalog = function(...args) {
    const groups = visibleGroups();
    const matching = new Set(filter(...args).map(item => groups.get(item.id)).filter(Boolean));
    return Array.from(matching, group => group.representative);
  };

  function isFavorite(group) {
    return state.exerciseFavorites.some(id => group.ids.has(id));
  }

  function updateFavorites(group, favorites, enabled) {
    const next = favorites.filter(id => !group.ids.has(id));
    if (enabled) next.push(group.representative.id);
    return next;
  }

  const toggleFavorite = toggleWorkoutFavorite;
  toggleWorkoutFavorite = function(catalogId) {
    const group = visibleGroups().get(catalogId);
    if (!group || group.ids.size === 1) return toggleFavorite(catalogId);
    const favorites = updateFavorites(group, state.exerciseFavorites, !isFavorite(group));
    if (commitWorkoutChange({exerciseFavorites:favorites})) renderWorkoutCatalog();
  };

  const favoriteField = document.getElementById('workoutExerciseFavorite');
  const fillExercise = fillWorkoutExerciseFields;
  fillWorkoutExerciseFields = function(...args) {
    const result = fillExercise(...args);
    if (workoutExerciseMode === 'catalog') {
      const group = visibleGroups().get(editCatalogId.value);
      if (group && group.ids.size > 1) favoriteField.checked = isFavorite(group);
    }
    return result;
  };

  const getChanges = workoutCatalogChanges;
  workoutCatalogChanges = function(exercise) {
    const result = getChanges(exercise);
    if (workoutExerciseMode === 'catalog') {
      const group = visibleGroups().get(editCatalogId.value);
      if (group && group.ids.size > 1) {
        result.changes.exerciseFavorites = updateFavorites(
          group, result.changes.exerciseFavorites || state.exerciseFavorites, favoriteField.checked
        );
      }
    }
    return result;
  };

  deleteCatalogExercise = function(catalogId, fromEditor = false) {
    const group = visibleGroups().get(catalogId);
    if (!group) return;
    const count = group.ids.size;
    const explanation = count > 1 ? ' Os ' + count + ' cadastros equivalentes serão ocultados.' : '';
    if (!confirm('Excluir “' + group.representative.name + '” do catálogo?' + explanation + ' As fichas e o histórico serão preservados.')) return;

    const overrides = {...state.exerciseCatalogOverrides};
    const catalog = state.exerciseCatalog.map(item =>
      group.ids.has(item.id) ? {...item, catalogRemoved:true} : item
    );
    for (const item of workoutCatalogItems()) {
      if (item.source === 'app' && group.ids.has(item.id)) {
        overrides[item.id] = {...overrides[item.id], catalogRemoved:true};
      }
    }
    if (!commitWorkoutChange({
      exerciseCatalog:catalog,
      exerciseCatalogOverrides:overrides,
      exerciseFavorites:updateFavorites(group, state.exerciseFavorites, false)
    }, '', false)) return;

    if (fromEditor) closeDialog('workoutExerciseDialog');
    renderWorkoutCatalog();
    toast('Exercício removido do catálogo.');
  };

  editorDelete?.addEventListener('click', event => {
    if (workoutExerciseMode !== 'catalog' ||
        !document.getElementById('workoutExerciseDialog').classList.contains('open')) return;
    event.stopImmediatePropagation();
    deleteCatalogExercise(editCatalogId.value, true);
  }, true);

  const render = renderWorkoutCatalog;
  renderWorkoutCatalog = function() {
    const result = render();
    const groups = visibleGroups();
    for (const card of root.querySelectorAll('.workout-catalog-card[data-catalog-id]')) {
      const catalogId = card.dataset.catalogId;
      const group = groups.get(catalogId);
      if (group && group.ids.size > 1) {
        const star = card.querySelector('.workout-star');
        const starred = isFavorite(group);
        star.textContent = starred ? '★' : '☆';
        star.setAttribute('aria-pressed', String(starred));
      }
      const actions = card.querySelector('.workout-actions');
      if (!actions || actions.querySelector('button.danger')) continue;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'btn danger';
      button.textContent = 'Excluir do catálogo';
      button.addEventListener('click', () => deleteCatalogExercise(catalogId));
      actions.append(button);
    }
    return result;
  };
})();
